//! Canonical readonly owner accessors for native form controls.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><form id=owner><input id=input name=input value=seed><button id=button name=button type=button>Button</button><select id=select name=select><option>One</option></select><textarea id=textarea name=textarea>seed</textarea></form><form id=other></form><input id=external form=other></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://control-form-accessor.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn control_form_accessor_canonical_native_owner_descriptors(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var owner=document.getElementById('owner'),other=document.getElementById('other'),interfaces=[HTMLInputElement,HTMLButtonElement,HTMLSelectElement,HTMLTextAreaElement],ids=['input','button','select','textarea'];for(var i=0;i<interfaces.length;i++){var control=document.getElementById(ids[i]),a=Object.getOwnPropertyDescriptor(interfaces[i].prototype,'form');if(!a||typeof a.get!=='function'||a.set!==undefined||!a.enumerable||!a.configurable||a.get.name!=='get form'||a.get.length!==0||Object.hasOwn(control,'form')||a.get.call(control)!==owner||control.form!==owner)throw 'canonical native form owner';}if(document.getElementById('external').form!==other)throw 'external native owner';"#);}
#[test]
fn control_form_accessor_inert_exact_connected_owner_and_detached_ancestor(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var doc=new Document(),html='http://www.w3.org/1999/xhtml',root=doc.createElementNS(html,'div'),a=doc.createElementNS(html,'form'),b=doc.createElementNS(html,'form');doc.appendChild(root);root.appendChild(a);root.appendChild(b);a.id='A\ud800z';b.id='A\udfffz';var interfaces=[HTMLInputElement,HTMLButtonElement,HTMLSelectElement,HTMLTextAreaElement],tags=['input','button','select','textarea'];for(var i=0;i<tags.length;i++){var c=doc.createElementNS(html,tags[i]),get=Object.getOwnPropertyDescriptor(interfaces[i].prototype,'form').get;a.appendChild(c);if(c.form!==a||get.call(c)!==a)throw 'inert ancestor owner';c.setAttribute('form','A\udfffz');if(c.form!==b||get.call(c)!==b)throw 'exact explicit owner';c.setAttribute('form','A�z');if(c.form!==null)throw 'scalar owner alias';c.setAttribute('form','A\udfffz');var detached=doc.createElementNS(html,'form');detached.appendChild(c);if(c.form!==detached||get.call(c)!==detached)throw 'detached ancestor overrides explicit attr';var copy=c.cloneNode(true);if(copy.form!==null||get.call(copy)!==null)throw 'fresh detached clone owner';} "#);}
#[test]
fn control_form_accessor_readonly_brands_and_author_shadow(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var interfaces=[HTMLInputElement,HTMLButtonElement,HTMLSelectElement,HTMLTextAreaElement],ids=['input','button','select','textarea'],owner=document.getElementById('owner');for(var i=0;i<interfaces.length;i++){var c=document.getElementById(ids[i]),proto=interfaces[i].prototype,a=Object.getOwnPropertyDescriptor(proto,'form');if(!a)throw 'missing canonical owner';c.form='author';if(c.form!==owner||Object.hasOwn(c,'form'))throw 'sloppy readonly owner';var caught=false;try{(function(){'use strict';c.form='author';})();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'strict readonly owner';for(var bad of [{},Object.create(proto),document.getElementById('owner'),document.createElement('div'),document.createElementNS('urn:foreign',ids[i])]){caught=false;try{a.get.call(bad);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'genuine concrete control brand';}if(c.form!==owner||a.get.call(c)!==owner||Object.hasOwn(c,'form'))throw 'canonical native owner';}"#);}

#[test]
fn control_form_accessor_concrete_getters_reject_other_control_interfaces(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var interfaces=[HTMLInputElement,HTMLButtonElement,HTMLSelectElement,HTMLTextAreaElement],ids=['input','button','select','textarea'];for(var i=0;i<interfaces.length;i++){var get=Object.getOwnPropertyDescriptor(interfaces[i].prototype,'form').get;for(var j=0;j<interfaces.length;j++){if(i===j)continue;var caught=false;try{get.call(document.getElementById(ids[j]));}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'concrete owner brand';}var a=Object.getOwnPropertyDescriptor(interfaces[i].prototype,'form'),c=document.getElementById(ids[i]),owner=c.form;Object.defineProperty(interfaces[i].prototype,'form',{value:'prototype',configurable:true});if(c.form!=='prototype'||get.call(c)!==owner)throw 'prototype owner shadow';delete interfaces[i].prototype.form;if(c.form!==undefined||get.call(c)!==owner)throw 'deleted native owner';Object.defineProperty(interfaces[i].prototype,'form',a);if(c.form!==owner||Object.hasOwn(c,'form'))throw 'canonical concrete owner restore';}"#);}
#[test]
fn control_form_accessor_saved_child_origin_refuses_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var savedDefine=frame.contentWindow.Function('target',"Object.defineProperty(target,'form',{value:null});"),control=document.getElementById('input'),owner=document.getElementById('owner'),interfaces=[frame.contentWindow.HTMLInputElement,frame.contentWindow.HTMLButtonElement,frame.contentWindow.HTMLSelectElement,frame.contentWindow.HTMLTextAreaElement],ids=['input','button','select','textarea'],gets=[];for(var i=0;i<interfaces.length;i++){gets.push(Object.getOwnPropertyDescriptor(interfaces[i].prototype,'form').get);if(gets[i].call(document.getElementById(ids[i]))!==owner)throw 'saved child owners';}"#);let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.set_location(&crate::navigation::address("https://foreign-control-form.test/",&crate::navigation::Location::home()).unwrap());for i in 0..4{p.begin_job();let source=format!("gets[{i}].call(document.getElementById(ids[{i}]));");let e=p.runtime.execute(&source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);}p.begin_job();let e=p.runtime.execute("savedDefine(control);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.set_location(&crate::navigation::address("https://control-form-accessor.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"for(var i=0;i<gets.length;i++)if(gets[i].call(document.getElementById(ids[i]))!==owner)throw 'saved owner recovery';");}
#[test]
fn control_form_accessor_inert_adoption_and_first_id_blocker_authority(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"var html='http://www.w3.org/1999/xhtml',doc=new Document(),root=doc.createElementNS(html,'div'),form=doc.createElementNS(html,'form'),blocker=doc.createElementNS(html,'div');doc.appendChild(root);root.appendChild(blocker);root.appendChild(form);form.id='target';blocker.id='target';var tags=['input','button','select','textarea'],interfaces=[HTMLInputElement,HTMLButtonElement,HTMLSelectElement,HTMLTextAreaElement];for(var i=0;i<tags.length;i++){var o=doc.createElementNS(html,tags[i]),get=Object.getOwnPropertyDescriptor(interfaces[i].prototype,'form').get;form.appendChild(o);o.setAttribute('form','target');if(get.call(o)!==null||o.form!==null)throw 'first ID blocker';blocker.id='different';if(o.form!==form)throw 'current exact ID recovery';blocker.id='target';var target=new Document(),targetForm=target.createElementNS(html,'form');targetForm.id='target';target.appendChild(targetForm);target.adoptNode(o);if(o.form!==null||get.call(o)!==null)throw 'detached adopted owner';targetForm.appendChild(o);if(o.ownerDocument!==target||o.form!==targetForm||get.call(o)!==targetForm)throw 'current adopted owner';Object.defineProperty(o,'form',{get:function(){throw 'author owner';},configurable:true});if(get.call(o)!==targetForm)throw 'native owner authority';delete o.form;}"#);}
#[test]
fn control_form_accessor_native_limits_recover_without_copy_or_storage(){for &(interface,method) in script_control_form::GETTERS{for expired in [false,true]{let(mut d,mut f,mut p)=fixture();let id=match interface{"HTMLInputElement"=>"input","HTMLButtonElement"=>"button","HTMLSelectElement"=>"select",_=>"textarea"};let n=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()==id)).unwrap();let owner=(0..d.nodes.len()).find(|&n|d.dom_attr(n,"id").is_some_and(|v|v.as_str()=="owner")).unwrap();p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone());p.begin_job();if expired{p.state.execution_deadline=Some(Instant::now());}else{p.state.host_work=0;}let e=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_form_get(node_handle(n),method).unwrap_err();assert!(e.contains("work")||e.contains("time"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);p.begin_job();p.state.execution_deadline=None;p.state.retained_limit=p.state.retained;p.state.copy_work=0;p.state.limits.host.string_bytes=0;let result=Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}.control_form_get(node_handle(n),method).unwrap();assert!(matches!(result,Value::Host(form)if form==node_handle(owner)));assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),state);}}}
#[test]
fn control_form_accessor_readonly_never_converts_and_native_reassociation_guard_stays(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var input=document.getElementById('input'),owner=document.getElementById('owner'),calls=0;input.form={toString:function(){calls++;return 'other';}};if(calls||input.form!==owner)throw 'readonly native form conversion';");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);p.begin_job();let e=p.runtime.execute("input.setAttribute('form','other');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("form")||e.contains("Supported attributes"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);p.begin_job();run(&mut d,&mut f,&mut p,"if(calls||input.form!==owner)throw 'native association refusal recovery';");}

#[test]
fn control_form_accessor_widget_descriptor_refusal_precedes_author_fields(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var ids=['input','button','select','textarea'],calls=0,descriptor={};Object.defineProperty(descriptor,'get',{get:function(){calls++;return function(){return null;};}});");let before=format!("{:?}",d.nodes);let state=(p.state.retained,p.state.dom_commits);for i in 0..4{p.begin_job();let source=format!("Object.defineProperty(document.getElementById(ids[{i}]),'form',descriptor);");let e=p.runtime.execute(&source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("descriptor")||e.contains("Native"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits),state);}p.begin_job();run(&mut d,&mut f,&mut p,"if(calls)throw 'descriptor guard before author fields';for(var id of ids)if(document.getElementById(id).form!==document.getElementById('owner'))throw 'native owner retained after refused descriptor';");}
